require_once "auth.php";requireAdmin();require_once "db.php";
$r=$conn->query("SELECT s.id,s.student_name,s.phone,s.student_image,s.created_at,c.course_name FROM students s LEFT JOIN course_student cs ON s.id=cs.student_id LEFT JOIN course c ON cs.course_id=c.id ORDER BY s.id DESC");
