<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>الطلاب</title><link rel="stylesheet" href="style.css"></head><body><nav><b>🎓 منصة الكورسات</b><a href="index.php">Dashboard</a><a href="add_course.php">إضافة كورس</a><a href="logout.php">خروج</a></nav><div class="wrap"><section class="hero"><h1>👨‍🎓 الطلاب</h1><div class="stats"><div class="stat"><strong><?=$total?></strong>إجمالي الطلاب</div></div></section><input id="q" placeholder="بحث باسم الطالب أو الهاتف أو الكورس..."><br><br><div class="table"><table id="t"><tr><th>الطالب</th><th>الهاتف</th><th>الكورس</th><th>التاريخ</th><th>الإجراءات</th></tr><?php while($s=$r->fetch_assoc()):?><tr><td><?php if($s["student_image"]&&is_file(__DIR__."/".$s["student_image"])):?><img class="student-img" src="<?=htmlspecialchars($s["student_image"],ENT_QUOTES,"UTF-8")?>" alt=""><?php endif;?><?=htmlspecialchars($s["student_name"],ENT_QUOTES,"UTF-8")?></td><td><?=htmlspecialchars($s["phone"]??"",ENT_QUOTES,"UTF-8")?></td><td><?=htmlspecialchars($s["course_name"]??"غير مرتبط",ENT_QUOTES,"UTF-8")?></td><td><?=htmlspecialchars($s["created_at"]??"",ENT_QUOTES,"UTF-8")?></td><td class="actions"><a class="btn" href="edit_student.php?id=<?=$s["id"]?>">تعديل</a><form method="post" action="delete_student.php" onsubmit="return confirm('حذف الطالب؟')"><input type="hidden" name="id" value="<?=$s["id"]?>"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrf_token(),ENT_QUOTES,"UTF-8")?>"><button class="btn-danger">حذف</button></form></td></tr><?php endwhile;?></table></div></div><script>q.oninput=()=>{let v=q.value.toLowerCase();document.querySelectorAll('#t tr:not(:first-child)').forEach(x=>x.style.display=x.innerText.toLowerCase().includes(v)?'':'none')}</script></body></html>